INSERT INTO playstore_reviews (
  package_name, review_id, author, rating, review_text, language, device,
  android_os_version, app_version, thumbs_up_count, posted_at, replied,
  reply_text, reply_posted_at, source, raw_data
)
SELECT
  package_name, review_id, author, rating, review_text, language, device,
  android_os_version, app_version, COALESCE(thumbs_up_count, 0), posted_at,
  COALESCE(replied, false), reply_text, reply_posted_at, source, raw_data
FROM seed_rows
ON CONFLICT (review_id) DO UPDATE SET
  package_name = EXCLUDED.package_name,
  author = EXCLUDED.author,
  rating = EXCLUDED.rating,
  review_text = EXCLUDED.review_text,
  language = EXCLUDED.language,
  device = EXCLUDED.device,
  android_os_version = EXCLUDED.android_os_version,
  app_version = EXCLUDED.app_version,
  thumbs_up_count = EXCLUDED.thumbs_up_count,
  posted_at = EXCLUDED.posted_at,
  replied = EXCLUDED.replied,
  reply_text = EXCLUDED.reply_text,
  reply_posted_at = EXCLUDED.reply_posted_at,
  source = EXCLUDED.source,
  raw_data = EXCLUDED.raw_data,
  scraped_at = NOW();

SELECT COUNT(*) AS playstore_reviews_count FROM playstore_reviews;
